const body = $input.first().json.body || $input.first().json;
if (!body.narration_script) throw new Error('narration_script is required');
if (!body.title) throw new Error('title is required');
const QUALITY_CAPS = { draft: 3, standard: 5, premium: 8 };
const qualityMode = ['draft','standard','premium'].includes(body.quality_mode) ? body.quality_mode : null;
const sceneMax = qualityMode ? QUALITY_CAPS[qualityMode] : 20;
const sceneCount = body.scene_count ? Math.max(3, Math.min(sceneMax, parseInt(body.scene_count))) : null;
const targetDuration = body.target_duration_sec ? Math.max(15, parseInt(body.target_duration_sec)) : null;
const aspectRatio = ['16:9','9:16','1:1'].includes(body.aspect_ratio) ? body.aspect_ratio : '16:9';
const sceneSeconds = (sceneCount && targetDuration)
  ? Math.max(2, Math.round(targetDuration / sceneCount))
  : (body.scene_seconds || parseInt($env.SCENE_VIDEO_SECONDS || '8'));
const niche = body.channel_niche || $env.CHANNEL_NICHE || 'general';
const language = body.language || $env.CHANNEL_LANGUAGE || 'English';
const visualStyle = body.visual_style || $env.CHANNEL_VISUAL_STYLE || 'cinematic';
const projectDesc = body.project_description || '';
const userBase = (body.script_base_prompt || '').trim();
const defaultBase = `You are a senior video director and screenwriter for a ${niche} channel targeting ${language}-speaking viewers. Your job: break a narration script into vivid, cinematic scenes that flow with strong visual continuity and emotional pacing.

Rules:
- Output STRICT JSON only — no markdown, no commentary.
- Each scene must have visual coherence with adjacent scenes (same setting, lighting mood, characters).
- image_prompt: photographic, specific (subject + setting + lighting + composition), aspect ratio ${aspectRatio}. No text overlays.
- video_prompt: short imperative motion description (e.g., "slow dolly-in", "hand-held tracking shot"). Must match the image.
- camera_motion: one of [static, pan_left, pan_right, dolly_in, dolly_out, tilt_up, tilt_down, tracking].
- sound_design: ambient cue keyword (e.g., "rain, distant thunder", "market chatter").
- narration_excerpt: literal sentence(s) from the input script — do NOT paraphrase.
- The scenes array length MUST equal the requested scene count.
- Visual style: ${visualStyle}.${projectDesc ? `\n- Channel context: ${projectDesc}` : ''}`;
const systemPrompt = userBase || defaultBase;

// ── Providers: pushed by backend source.service for dynamic routing ──
const providers = body.providers || null;
if (!providers || !providers.script) throw new Error('providers.script is null — set project Script provider (google/anthropic) and add an active SCRIPT key in API Sources');
if (!providers.image) throw new Error('providers.image is null — set project Image provider = google, model = gemini-2.5-flash-image-preview and add an active IMAGE key in API Sources');

// Build user message (moved here so script_request can inline it)
const sceneCountLabel = sceneCount || 'an appropriate number of';
const durationLabel = targetDuration || (sceneSeconds * 8);
const userMessage = `Break this script into EXACTLY ${sceneCountLabel} scenes. Total target duration: ${durationLabel}s (~${sceneSeconds}s each). Aspect ratio: ${aspectRatio}.\n\nReturn JSON shape:\n{\n  "style_bible": "global visual rules (palette, lens, lighting, character DNA) used across all scenes",\n  "scenes": [{ "scene_id": 1, "start_sec": 0, "end_sec": 8, "narration_excerpt": "...", "image_prompt": "...", "video_prompt": "...", "camera_motion": "dolly_in", "sound_design": "..." }]\n}\n\nTitle: ${body.title}\n\nScript:\n${body.narration_script}`;

// Build script_request based on provider format (claude_messages vs openai_chat)
let script_request;
const fmt = providers.script.requestFormat;
if (fmt === 'claude_messages') {
  script_request = {
    url: providers.script.url,
    headers: {
      'x-api-key': providers.script.authValue,
      'anthropic-version': ((providers.script.extraHeaders || {})['anthropic-version'] || '2023-06-01'),
      'content-type': 'application/json',
    },
    body: { model: providers.script.model, max_tokens: 4096, system: systemPrompt, messages: [{ role: 'user', content: userMessage }] },
  };
} else {
  // openai_chat — Gemini OpenAI-compat endpoint
  script_request = {
    url: providers.script.url,
    headers: { [providers.script.authName]: providers.script.authValue, 'content-type': 'application/json' },
    body: { model: providers.script.model, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }] },
  };
}

const config = {
  projectId:           body.projectId || '',
  episode_id:          body.episode_id || `ep_${new Date().getTime()}`,
  title:               body.title,
  narration_script:    body.narration_script,
  thumbnail_text:      body.thumbnail_text || body.title,
  seo_keywords:        body.seo_keywords || [],
  core_emotion:        body.core_emotion || null,
  channel_niche:       niche,
  language:            language,
  visual_style:        visualStyle,
  project_description: projectDesc,
  system_prompt:       systemPrompt,
  user_base_override:  !!userBase,
  scene_seconds:       sceneSeconds,
  scene_count:         sceneCount,
  target_duration_sec: targetDuration,
  aspect_ratio:        aspectRatio,
  workspace:           '/data/pipeline',
  providers,
  script_request,
  quality_mode:        qualityMode,
  voice_script:        body.voice_script || null,
  character_id:        body.character_id || null,
};
return [{ json: config }];

const resp = $input.first().json;
// Support both openai_chat (choices[0].message.content) and claude_messages (content[0].text)
const raw = resp.choices?.[0]?.message?.content ?? resp.content?.[0]?.text ?? resp.output_text ?? '{}';
const cleaned = raw.replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim();
let plan;
try { plan = JSON.parse(cleaned); }
catch(e) { throw new Error('Cannot parse scene plan: ' + cleaned.slice(0,300)); }
const base = $('Code - Validate Input').first().json;
return [{ json: { ...base, scene_plan: plan } }];

const base = $input.first().json;
const scenes = base.scene_plan.scenes || [];
return scenes.map(scene => ({
  json: {
    episode_id: base.episode_id,
    title: base.title,
    narration_script: base.narration_script,
    thumbnail_text: base.thumbnail_text,
    seo_keywords: base.seo_keywords,
    core_emotion: base.core_emotion || null,
    style_bible: base.scene_plan.style_bible || '',
    scene
  }
}));

const base = $('Code - Split Scenes').all()[$itemIndex]?.json || {};
const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData?.data);
const b64 = imgPart?.inlineData?.data || null;
const mime = imgPart?.inlineData?.mimeType || 'image/png';
const url = b64 ? `data:${mime};base64,${b64}` : null;
return [{ json: { ...base, image_url: url } }];

const items = $input.all().map(i => i.json);
const base = items[0];
const cfg = $('Code - Validate Input').first().json;
const projectId = cfg.projectId || '';
const aspect = cfg.aspect_ratio || '16:9';
return [{ json: {
  projectId,
  episode_id: base.episode_id,
  workspace: '/data/pipeline',
  title: base.title,
  narration_script: base.narration_script,
  thumbnail_text: base.thumbnail_text,
  seo_keywords: base.seo_keywords || [],
  core_emotion: base.core_emotion || null,
  aspect_ratio: aspect,
  target_duration_sec: cfg.target_duration_sec || null,
  scene_count: cfg.scene_count || null,
  scenes: items.map((item, idx) => {
    const scene = item.scene || {};
    const sceneId = scene.scene_id || ('scene_' + (idx + 1));
    return {
      scene_id: String(sceneId),
      start_sec: scene.start_sec || 0,
      end_sec: scene.end_sec || cfg.scene_seconds || 8,
      narration_excerpt: scene.narration_excerpt || '',
      image_url: item.image_url,
      video_prompt: scene.video_prompt || scene.image_prompt || '',
      sound_design: scene.sound_design || 'ambient',
      aspect_ratio: aspect
    };
  })
} }];

const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData?.data);
const b64 = imgPart?.inlineData?.data || null;
const mime = imgPart?.inlineData?.mimeType || 'image/png';
const url = b64 ? `data:${mime};base64,${b64}` : null;
const manifest = $('Code - Build Manifest').first().json;
return [{ json: { ...manifest, thumbnail_url: url } }];
